# Update render_inner_html to resolve HTML placeholders
import subprocess
result = subprocess.run(
    ['cat', 'markdown/extensions/toc.py'],
    capture_output=True, text=True
)
content = result.stdout

old_func = '''def render_inner_html(md: Markdown, elem: etree.Element) -> str:
    """Serialize the inner HTML of an element (text + children, not the element itself)."""
    # Create a wrapper element containing the text and children
    wrapper = etree.Element("div")
    if elem.text:
        wrapper.text = elem.text
    for child in elem:
        # Skip footnote reference <sup> elements to prevent their text from leaking into TOC names
        if child.tag == 'sup' and 'fnref' in child.get('id', ''):
            continue
        wrapper.append(child)
        if child.tail:
            wrapper[-1].tail = child.tail
    return md.serializer(wrapper)'''

new_func = '''def render_inner_html(md: Markdown, elem: etree.Element) -> str:
    """Serialize the inner HTML of an element (text + children, not the element itself)."""
    # Resolve HTML placeholders in text content
    def resolve_stash(text):
        if text is None:
            return None
        def _html_sub(m):
            try:
                raw = md.htmlStash.rawHtmlBlocks[int(m.group(1))]
            except (IndexError, TypeError):
                return m.group(0)
            return raw
        return HTML_PLACEHOLDER_RE.sub(_html_sub, text)

    # Create a wrapper element containing the text and children
    wrapper = etree.Element("div")
    if elem.text:
        wrapper.text = resolve_stash(elem.text)
    for child in elem:
        # Skip footnote reference <sup> elements to prevent their text from leaking into TOC names
        if child.tag == 'sup' and 'fnref' in child.get('id', ''):
            continue
        wrapper.append(child)
        if child.tail:
            wrapper[-1].tail = resolve_stash(child.tail)
    return md.serializer(wrapper)'''

new_content = content.replace(old_func, new_func)

with open('markdown/extensions/toc.py', 'w') as f:
    f.write(new_content)

print("Updated render_inner_html")
